import json
import logging
from typing import Dict, Any, List, Optional, Set
from sqlalchemy.orm import Session
from ..models.models import (
    CandidatePrediction, EvidenceRecord, KnowledgeEdge,
    DrugInteraction, ClinicalTrialRecord, Disease, Drug
)
from ..schemas.schemas import StructuredSynthesisOut
from .biomedical_adapters import BiomedicalAdapter
from .llm_service import BaseLLMClient

logger = logging.getLogger("curenova.biomedical_agents")

NON_CLINICAL_DISCLAIMER = (
    "LEGAL & SCIENTIFIC RESEARCH BOUNDARY: All computational predictions generated by CureNova represent "
    "preclinical research hypotheses derived from knowledge graphs and biomedical literature. They are NOT "
    "clinical prescriptions, diagnostic determinations, or medical treatment guidelines. Experimental and "
    "clinical validation is mandatory before any therapeutic application."
)

class LiteratureScout:
    """
    Agent A: LiteratureScout.
    Retrieves verified scientific evidence records and publication metadata.
    Distinguishes retrieved facts from model interpretations and never invents citations.
    """
    @staticmethod
    async def run(
        db: Session,
        drug_name: str,
        disease_name: str,
        candidate_id: Optional[int] = None,
        include_live_pubmed: bool = False
    ) -> Dict[str, Any]:
        query = db.query(EvidenceRecord)
        if candidate_id:
            query = query.filter(EvidenceRecord.candidate_id == candidate_id)

        evidence_records = query.all()

        retrieved_facts = []
        verified_evidence_map: Dict[int, Dict[str, Any]] = {}
        for ev in evidence_records:
            item = {
                "id": ev.id,
                "title": ev.title,
                "pmid": ev.pmid,
                "doi": ev.doi,
                "journal": ev.journal,
                "year": ev.year,
                "study_type": ev.study_type,
                "evidence_direction": ev.evidence_direction,
                "excerpt": ev.excerpt,
                "provenance_url": ev.provenance_url or (f"https://pubmed.ncbi.nlm.nih.gov/{ev.pmid}/" if ev.pmid else None),
                "is_retrieved_fact": True
            }
            retrieved_facts.append(item)
            verified_evidence_map[ev.id] = item

        live_pubmed_results = []
        if include_live_pubmed:
            try:
                live_pubmed_results = await BiomedicalAdapter.search_pubmed(f"{drug_name} {disease_name}", max_results=3)
            except Exception as e:
                logger.warning("LiteratureScout PubMed live adapter skipped: %s", str(e))

        return {
            "evidence_count": len(retrieved_facts),
            "retrieved_facts": retrieved_facts,
            "verified_evidence_map": verified_evidence_map,
            "live_pubmed_results": live_pubmed_results
        }


class TargetMechanist:
    """
    Agent B: TargetMechanist.
    Analyzes plausible drug-disease and drug-target mechanisms using retrieved evidence and knowledge graph.
    Distinguishes established mechanisms from novel research hypotheses.
    """
    @staticmethod
    async def run(
        db: Session,
        drug_name: str,
        disease_name: str,
        evidence_facts: List[Dict[str, Any]],
        llm_client: Optional[BaseLLMClient] = None
    ) -> Dict[str, Any]:
        edges = db.query(KnowledgeEdge).all()
        relevant_edges = [
            e for e in edges
            if drug_name.lower() in e.source_id.lower() or drug_name.lower() in e.target_id.lower()
            or disease_name.lower() in e.source_id.lower() or disease_name.lower() in e.target_id.lower()
        ]

        supporting_ids = [e["id"] for e in evidence_facts if e.get("evidence_direction") == "supporting"]
        conflicting_ids = [e["id"] for e in evidence_facts if e.get("evidence_direction") == "contradictory"]

        # Deterministic mechanistic baseline
        pathway_desc = (
            f"Modulation of kinase/target signaling cascades relevant to {disease_name}. "
            f"Knowledge graph indicates {len(relevant_edges)} connected biological interaction edges."
        )
        is_established = any(e.relationship_type.lower() in ("treats", "targets") for e in relevant_edges)

        mechanistic_result = {
            "target_pathway": pathway_desc,
            "is_established": is_established,
            "supporting_evidence_ids": supporting_ids,
            "conflicting_evidence_ids": conflicting_ids,
            "biological_edges_count": len(relevant_edges)
        }

        # If LLM is active, enhance mechanistic reasoning grounded strictly on evidence
        if llm_client:
            system_prompt = (
                "You are CureNova TargetMechanist, an expert biomedical reasoning agent. "
                "Analyze biological mechanisms connecting the candidate drug to the disease. "
                "CRITICAL: Ground claims ONLY in the provided evidence. Cite supporting and conflicting IDs. "
                "Return JSON with keys: proposed_mechanism (str), is_established (bool), "
                "supporting_evidence_ids (list of int), conflicting_evidence_ids (list of int)."
            )
            user_prompt = (
                f"<candidate_context>\nDrug: {drug_name}\nDisease: {disease_name}\n</candidate_context>\n"
                f"<retrieved_evidence>\n{json.dumps(evidence_facts[:8])}\n</retrieved_evidence>"
            )
            try:
                llm_out = await llm_client.chat_completion(
                    system_prompt=system_prompt,
                    user_prompt=user_prompt,
                    temperature=0.2,
                    max_tokens=600,
                    response_json=True
                )
                if isinstance(llm_out, dict) and "proposed_mechanism" in llm_out:
                    mechanistic_result["target_pathway"] = str(llm_out["proposed_mechanism"])
                    if "is_established" in llm_out:
                        mechanistic_result["is_established"] = bool(llm_out["is_established"])
            except Exception as e:
                logger.warning("TargetMechanist LLM failure: %s", str(e))
                raise

        return mechanistic_result


class SafetyAssessor:
    """
    Agent C: SafetyAssessor.
    Audits polypharmacy interactions, adverse clinical signals, and explicit knowledge gaps.
    Never declares a drug safe due to missing records.
    """
    @staticmethod
    async def run(
        db: Session,
        drug_name: str,
        disease_name: str,
        evidence_facts: List[Dict[str, Any]],
        llm_client: Optional[BaseLLMClient] = None
    ) -> Dict[str, Any]:
        # Query known drug interactions
        all_ddis = db.query(DrugInteraction).all()
        matched_ddis = [
            {
                "drug_a": d.drug_a_name,
                "drug_b": d.drug_b_name,
                "severity": d.severity,
                "mechanism": d.mechanism,
                "recommendation": d.recommendation
            }
            for d in all_ddis
            if drug_name.lower() in d.drug_a_name.lower() or drug_name.lower() in d.drug_b_name.lower()
        ]

        # Contradictory evidence signals
        contradictory_ev = [e for e in evidence_facts if e.get("evidence_direction") == "contradictory"]
        contradictory_ids = [e["id"] for e in contradictory_ev]

        safety_concerns = []
        for d in matched_ddis:
            safety_concerns.append(f"DDI ({d['severity']}): {d['drug_a']} + {d['drug_b']} - {d['mechanism']}")
        for c in contradictory_ev:
            safety_concerns.append(f"Adverse/Contradictory literature signal: {c['title']} ({c.get('excerpt', '')[:100]}...)")

        missing_safety_data = []
        if not matched_ddis:
            missing_safety_data.append(
                f"No documented drug-drug interaction monograph for '{drug_name}' in local database. "
                "Explicit safety check required; absence of record does NOT imply absence of risk."
            )
        if not contradictory_ev:
            missing_safety_data.append("No adverse clinical trial records identified in current dataset partition.")

        safety_assessment = {
            "drug_name": drug_name,
            "safety_concerns": safety_concerns,
            "missing_safety_data": missing_safety_data,
            "matched_ddi_count": len(matched_ddis),
            "contradictory_evidence_ids": contradictory_ids,
            "uncertainty_warning": (
                "High epistemic uncertainty: preclinical scores do not capture whole-body metabolic "
                "or pharmacogenomic toxicities. Formal toxicology review mandatory."
            )
        }

        if llm_client:
            system_prompt = (
                "You are CureNova SafetyAssessor, an oncology and clinical safety auditor. "
                "Evaluate potential safety hazards, drug interactions, and contradictory trial evidence. "
                "CRITICAL: Never claim safety without evidence. Explicitly label missing data. "
                "Return JSON with keys: safety_concerns (list of str), missing_safety_data (list of str)."
            )
            user_prompt = (
                f"<candidate_context>\nDrug: {drug_name}\nDisease: {disease_name}\n</candidate_context>\n"
                f"<known_ddi>\n{json.dumps(matched_ddis)}\n</known_ddi>\n"
                f"<contradictory_evidence>\n{json.dumps(contradictory_ev)}\n</contradictory_evidence>"
            )
            try:
                llm_out = await llm_client.chat_completion(
                    system_prompt=system_prompt,
                    user_prompt=user_prompt,
                    temperature=0.2,
                    max_tokens=500,
                    response_json=True
                )
                if isinstance(llm_out, dict):
                    if "safety_concerns" in llm_out and isinstance(llm_out["safety_concerns"], list):
                        # Merge LLM findings with database ground truth
                        combined = list(dict.fromkeys(safety_concerns + [str(x) for x in llm_out["safety_concerns"]]))
                        safety_assessment["safety_concerns"] = combined
                    if "missing_safety_data" in llm_out and isinstance(llm_out["missing_safety_data"], list):
                        combined_missing = list(dict.fromkeys(missing_safety_data + [str(x) for x in llm_out["missing_safety_data"]]))
                        safety_assessment["missing_safety_data"] = combined_missing
            except Exception as e:
                logger.warning("SafetyAssessor LLM failure: %s", str(e))
                raise

        return safety_assessment


class Synthesizer:
    """
    Agent D: Synthesizer.
    Combines validated outputs from Scout, Mechanist, and Assessor.
    Enforces strict citation verification against retrieved evidence records.
    Rejects unsupported IDs and guarantees scientific boundaries.
    """
    @staticmethod
    async def run(
        drug_name: str,
        disease_name: str,
        evidence_facts: List[Dict[str, Any]],
        mechanistic_data: Dict[str, Any],
        safety_data: Dict[str, Any],
        llm_client: Optional[BaseLLMClient] = None
    ) -> StructuredSynthesisOut:
        # Build set of valid evidence IDs that actually exist
        valid_ids: Set[int] = {e["id"] for e in evidence_facts if isinstance(e.get("id"), int)}
        evidence_by_id = {e["id"]: e for e in evidence_facts if isinstance(e.get("id"), int)}

        proposed_mech = mechanistic_data.get("target_pathway", "Hypothetical receptor/kinase modulation.")
        rationale = f"Evaluated repurposing potential of {drug_name} for {disease_name} across {len(evidence_facts)} evidence records."
        supp_ids = [i for i in mechanistic_data.get("supporting_evidence_ids", []) if i in valid_ids]
        conf_ids = [i for i in safety_data.get("contradictory_evidence_ids", []) if i in valid_ids]
        safety_concerns = safety_data.get("safety_concerns", [])
        missing_info = safety_data.get("missing_safety_data", [])
        strength = "Moderate (Phase 2/Clinical)" if any("clinical" in str(e.get("study_type", "")).lower() for e in evidence_facts) else "Preliminary Preclinical"

        rejected_ids: List[int] = []

        if llm_client:
            system_prompt = (
                "You are CureNova Synthesizer, a principal biomedical researcher. "
                "Synthesize findings from LiteratureScout, TargetMechanist, and SafetyAssessor into a structured report. "
                "CRITICAL RULES:\n"
                "1. Cite ONLY valid evidence IDs provided in the context.\n"
                "2. If citing an evidence ID, it MUST be an integer from the provided list.\n"
                "3. Never present hypotheses as proven treatments.\n"
                "Return JSON with keys: research_rationale (str), proposed_mechanism (str), "
                "supporting_evidence_ids (list of int), conflicting_evidence_ids (list of int), "
                "safety_concerns (list of str), missing_information (list of str), "
                "evidence_strength (str), epistemic_uncertainty (float between 0.05 and 0.95)."
            )
            user_prompt = (
                f"<candidate>\nDrug: {drug_name}\nDisease: {disease_name}\n</candidate>\n"
                f"<valid_evidence_records>\n{json.dumps([{'id': e['id'], 'title': e['title'], 'direction': e['evidence_direction']} for e in evidence_facts])}\n</valid_evidence_records>\n"
                f"<mechanistic_summary>\n{json.dumps(mechanistic_data)}\n</mechanistic_summary>\n"
                f"<safety_summary>\n{json.dumps(safety_data)}\n</safety_summary>"
            )
            try:
                llm_out = await llm_client.chat_completion(
                    system_prompt=system_prompt,
                    user_prompt=user_prompt,
                    temperature=0.2,
                    max_tokens=1000,
                    response_json=True
                )
                if isinstance(llm_out, dict):
                    if "research_rationale" in llm_out:
                        rationale = str(llm_out["research_rationale"])
                    if "proposed_mechanism" in llm_out:
                        proposed_mech = str(llm_out["proposed_mechanism"])
                    if "evidence_strength" in llm_out:
                        strength = str(llm_out["evidence_strength"])
                    if "safety_concerns" in llm_out and isinstance(llm_out["safety_concerns"], list):
                        safety_concerns = [str(x) for x in llm_out["safety_concerns"]]
                    if "missing_information" in llm_out and isinstance(llm_out["missing_information"], list):
                        missing_info = [str(x) for x in llm_out["missing_information"]]

                    # Audit and validate citations returned by LLM
                    candidate_supp = llm_out.get("supporting_evidence_ids", [])
                    if isinstance(candidate_supp, list):
                        for cid in candidate_supp:
                            if isinstance(cid, int) and cid in valid_ids:
                                if cid not in supp_ids:
                                    supp_ids.append(cid)
                            else:
                                rejected_ids.append(cid)

                    candidate_conf = llm_out.get("conflicting_evidence_ids", [])
                    if isinstance(candidate_conf, list):
                        for cid in candidate_conf:
                            if isinstance(cid, int) and cid in valid_ids:
                                if cid not in conf_ids:
                                    conf_ids.append(cid)
                            else:
                                rejected_ids.append(cid)
            except Exception as e:
                logger.warning("Synthesizer LLM failure: %s", str(e))
                raise

        # Build validated citations list
        all_cited_ids = list(dict.fromkeys(supp_ids + conf_ids))
        validated_citations = []
        for cid in all_cited_ids:
            if cid in evidence_by_id:
                rec = evidence_by_id[cid]
                validated_citations.append({
                    "id": cid,
                    "pmid": rec.get("pmid"),
                    "title": rec.get("title"),
                    "direction": rec.get("evidence_direction"),
                    "provenance_url": rec.get("provenance_url")
                })

        limitations = (
            f"Analysis bounded by available retrospective preclinical records for {drug_name}. "
            "Graph ranking relies on public relational databases; novel allosteric binding or "
            "unmodeled tissue distribution cannot be ruled out."
        )

        return StructuredSynthesisOut(
            candidate_drug=drug_name,
            target_disease=disease_name,
            research_rationale=rationale,
            proposed_mechanism=proposed_mech,
            supporting_evidence_ids=supp_ids,
            conflicting_evidence_ids=conf_ids,
            safety_concerns=safety_concerns,
            missing_information=missing_info,
            evidence_strength=strength,
            epistemic_uncertainty=0.18 if conf_ids else 0.12,
            validated_citations=validated_citations,
            rejected_unsupported_ids=list(dict.fromkeys(rejected_ids)),
            research_limitations=limitations,
            non_clinical_disclaimer=NON_CLINICAL_DISCLAIMER
        )
